import { Container, Row, Col } from "react-bootstrap";
import navIcon1 from "../assets/img/nav-icon1.svg";
import navIcon2 from "../assets/img/nav-icon2.svg";
import navIcon3 from "../assets/img/nav-icon3.svg";

export const Footer = () => {
  return (
    <>
      <footer className="footer">
        <Container>
          <Row className="align-items-center justify-content-between">

            {/* Left Side - About */}
            <Col md={6} className="text-center text-md-start mb-4 mb-md-0">
              <h4 className="footer-title">Akash Kalatippi</h4>
              <p className="footer-desc">
                Passionate Full Stack Developer | MERN Stack Enthusiast  
                Building modern and user-friendly web experiences 🚀
              </p>
            </Col>

            {/* Right Side - Social Links */}
            <Col md={6} className="text-center text-md-end">
              <div className="social-icon mb-3">

                <a
                  href="https://www.linkedin.com/in/akashkalatippi"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <img src={navIcon1} alt="LinkedIn" />
                </a>

                <a
                  href="https://github.com/AkashKalatippi"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <img src={navIcon2} alt="GitHub" />
                </a>

                <a
                  href="https://www.instagram.com/akash_kalatippi"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <img src={navIcon3} alt="Instagram" />
                </a>

              </div>

              <p className="copyright">
                © {new Date().getFullYear()} Akash Kalatippi. All Rights Reserved
              </p>
            </Col>

          </Row>
        </Container>
      </footer>

      {/* Internal Styling */}
      <style>{`
        .footer {
          background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
          padding: 60px 0 40px 0;
          color: white;
        }

        .footer-title {
          font-size: 22px;
          font-weight: 600;
          margin-bottom: 10px;
        }

        .footer-desc {
          font-size: 14px;
          opacity: 0.85;
          max-width: 400px;
        }

        .social-icon a {
          margin: 0 10px;
          display: inline-block;
          transition: 0.3s ease;
        }

        .social-icon img {
          width: 32px;
        }

        .social-icon a:hover {
          transform: translateY(-6px) scale(1.1);
        }

        .copyright {
          font-size: 13px;
          opacity: 0.7;
        }
      `}</style>
    </>
  );
};
